]

def compute_backward_fill(grid):
    h, w = len(grid), len(grid[0])
    output = [[0]*w for _ in range(h)]

    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0:
                output[i][j] = grid[i][j]
            else:
                # Look backward along anti-diagonal (top-left to bottom-right)
                for k in range(1, max(i+1, j+1)):
                    vi, vj = i-k, j-k
                    if vi >= 0 and vj >= 0:
                        if grid[vi][vj] != 0:
                            output[i][j] = grid[vi][vj]
                            break
    return output

