        # Test diagonal-based (i+j) vs row-based (i)

        # Diagonal test: output[i][j] should only depend on (i+j)%k
        diag_consistent = True
        for i in range(h):
            for j in range(h):
                for ii in range(h):
                    for jj in range(h):
                        if (i+j) % k == (ii+jj) % k:
                            if grid[i][j] != grid[ii][jj]:
                                diag_consistent = False
                                break
                    if not diag_consistent:
                        break
                if not diag_consistent:
                    break
            if not diag_consistent:
                break
        if diag_consistent:
            return k, 'diagonal'

        # Row test: output[i][j] should only depend on i % k
        row_consistent = True
        for i in range(h):
            for j in range(h):
                for ii in range(h):
                    if i % k == ii % k:
                        if grid[i][j] != grid[ii][jj]:
                            row_consistent = False
                            break
                if not row_consistent:
                    break
            if not row_consistent:
                break
        if row_consistent:
            return k, 'row'

    return None, None

