def find_output_type_and_period(grid):
    """Detect if output depends on diagonal (i+j) or row (i), and find period"""
    h = len(grid)

    # Check ranges for period
    for k in range(2, min(h, 20)):  # Limit search
        # Test diagonal
        diag_ok = True
        for i in range(h):
            for j in range(h):
                for ii in range(h):
                    for jj in range(h):
                        if (i+j) % k == (ii+jj) % k:
                            if grid[i][j] != grid[ii][jj]:
                                diag_ok = False
                                break
                if not diag_ok:
                    break
            if not diag_ok:
                break
        if diag_ok:
            return k, 'diagonal'

        # Test row
        row_ok = True
        for i in range(h):
            for j in range(h):
                for ii in range(h):
                    for jj in range(h):
                        if i % k == ii % k:
                            if grid[i][j] != grid[ii][jj]:
