                                break
                if not row_ok:
                    break
            if not row_ok:
                break
        if row_ok:
            return k, 'row'

    return None, None

def derive_cycle(grid, period, dep='diagonal'):
    """Derive base cycle from grid cells"""
    h = len(grid)
    cycle = [0] * period

    if dep == 'diagonal':
        for r in range(h):
            for c in range(h):
                if grid[r][c] != 0:
                    m = (r+c) % period
                    if cycle[m] == 0:
                        cycle[m] = grid[r][c]
    else:  # row
        for r in range(h):
            vals = [v for v in grid[r] if v != 0]
            if vals:
                m = r % period
                if cycle[m] == 0:
                    cycle[m] = vals[0]

    return cycle

def construct_output(grid, period, cycle, dep='diagonal'):
    """Construct output from cycle"""
    h = len(grid)
    if dep == 'diagonal':
        return [[cycle[(i+j)%period] for j in range(h)] for i in range(h)]
    else:
        return [[cycle[i%period] for j in range(h)] for i in range(h)]

def test_transform(grid, cycle, dep='diagonal'):
    """Test if transform matches expected output"""
    h = len(grid)
    pred = construct_output(grid, len(cycle), cycle, dep)
    for i in range(h):
        for j in range(h):
            if pred[i][j] != grid[i][j]:
                return False, (i, j), pred[i][j], grid[i][j]
    return True, None, None, None

